// Prisma configuration (generated by Prisma and customised for CareerConnect).
import "dotenv/config";
import { defineConfig } from "prisma/config";

// `prisma generate` does not connect to the database, so a placeholder URL is
// safe and keeps `npm install` working before the developer creates a .env.
const databaseUrl =
  process.env.DATABASE_URL ||
  "postgresql://postgres:postgres@localhost:5432/careerconnect";

export default defineConfig({
  schema: "prisma/schema.prisma",
  migrations: {
    path: "prisma/migrations",
    seed: "node prisma/seed.js",
  },
  engine: "classic",
  datasource: {
    url: databaseUrl,
  },
});
